-- =====================================================================
-- V7_15 — 3 HR pages: Employee + Role + Department.
-- Proves the platform extends beyond M10/Dispatch — the same Schema V2
-- list view substrate serves HR domain with zero new code.
-- =====================================================================









UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:employee-master','pico:role-master','pico:department-master') AND current_version_id IS NULL;
